package com.nopilot.aiservice.model;  import java.util.Map; import java.util.UUID;  /**  * A chunk returned by the vector store, decoupled from Spring AI's Document type  * so the retrieval logic (isolation, de-duplication, packing) is plain testable Java.  */ public record RetrievedChunk(String id, double score, Map<String, Object> metadata, String text) {      public static final String META_REPOSITORY_ID = "repositoryId";     public static final String META_FILE_PATH = "filePath";     public static final String META_LANGUAGE = "language";     public static final String META_START_LINE = "startLine";     public static final String META_END_LINE = "endLine";     public static final String META_SYMBOL = "symbol";     public static final String META_CONTENT_HASH = "contentHash";      public String repositoryId() {         return string(META_REPOSITORY_ID);     }      public String filePath() {         return string(META_FILE_PATH);     }      public String language() {         return string(META_LANGUAGE);     }      public String symbol() {         return string(META_SYMBOL);     }      public String contentHash() {         return string(META_CONTENT_HASH);     }      public int startLine() {         return number(META_START_LINE);     }      public int endLine() {         return number(META_END_LINE);     }      public boolean belongsTo(UUID repositoryId) {         return repositoryId != null && repositoryId.toString().equals(repositoryId());     }      private String string(String key) {         Object value = metadata == null ? null : metadata.get(key);         return value == null ? null : value.toString();     }      private int number(String key) {         Object value = metadata == null ? null : metadata.get(key);         if (value instanceof Number number) {             return number.intValue();         }         if (value != null) {             try {                 return Integer.parseInt(value.toString());             } catch (NumberFormatException ignored) {                 return 0;             }         }         return 0;     } }
